class Solution {
    public int minNumber(int[] nums1,int[] nums2){
        boolean[] present=new boolean[10];
        for(int value:nums1)present[value]=true;
        int common=10;
        for(int value:nums2)if(present[value])common=Math.min(common,value);
        if(common<10)return common;
        int first=Arrays.stream(nums1).min().getAsInt(),second=Arrays.stream(nums2).min().getAsInt();
        return Math.min(first,second)*10+Math.max(first,second);
    }
}

code.kotlin:
class Solution {
    fun minNumber(nums1:IntArray,nums2:IntArray):Int{
        val present=BooleanArray(10);
        for(value in nums1)present[value]=true;
        var common=10;
        for(value in nums2)if(present[value])common=minOf(common,value);
        if(common<10)return common;
        val first=nums1.minOrNull()!!;
        val second=nums2.minOrNull()!!;
        return minOf(first,second)*10+maxOf(first,second)
    }
}

